insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values
  ('40000000-0000-4000-8000-000000000018','$6$','Encontre uma primitiva e aplique os limites.'),('40000000-0000-4000-8000-000000000019','$4$','A integral de uma constante é a constante multiplicada pela largura do intervalo.'),('40000000-0000-4000-8000-000000000020','$4/3$','Integre as duas parcelas e avalie entre zero e um.'),('40000000-0000-4000-8000-000000000021','$10$','Pelo Teorema Fundamental, uma integral definida é a diferença entre os valores de uma primitiva.'),('40000000-0000-4000-8000-000000000022','$11$','A derivada de uma integral com limite superior variável é o integrando avaliado nesse limite.'),('40000000-0000-4000-8000-000000000023','$0$','A função é ímpar e os limites são simétricos.'),('40000000-0000-4000-8000-000000000024','$-4$','Inverter os limites troca o sinal da integral.'),('40000000-0000-4000-8000-000000000025','$1$','Um limite inferior variável introduz sinal negativo ao derivar.'),('40000000-0000-4000-8000-000000000026','$5/2$','Separe a integral em zero, onde o valor absoluto muda de expressão.'),('40000000-0000-4000-8000-000000000027','$2$','A integral vale $c^2$; use a condição positiva para escolher a raiz.')
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values
  ('70000000-0000-4000-8000-000000000034','40000000-0000-4000-8000-000000000018','Aplique os limites','$[3x^2/2]_0^2=6$.',1),('70000000-0000-4000-8000-000000000035','40000000-0000-4000-8000-000000000019','Use a largura','$2(3-1)=4$.',1),('70000000-0000-4000-8000-000000000036','40000000-0000-4000-8000-000000000020','Integre','$[x^3/3+x^2]_0^1=1/3+1=4/3$.',1),('70000000-0000-4000-8000-000000000037','40000000-0000-4000-8000-000000000021','Use uma primitiva','$[x^3+x]_0^2=8+2=10$.',1),('70000000-0000-4000-8000-000000000038','40000000-0000-4000-8000-000000000022','Derive pelo TFC','$G''(x)=x^2+2$, então $G''(3)=11$.',1),('70000000-0000-4000-8000-000000000039','40000000-0000-4000-8000-000000000023','Use simetria','$x$ é ímpar; a integral em $[-1,1]$ é zero.',1),('70000000-0000-4000-8000-000000000040','40000000-0000-4000-8000-000000000024','Inverta os limites','$\int_2^0(x+1)dx=-\int_0^2(x+1)dx=-4$.',1),('70000000-0000-4000-8000-000000000041','40000000-0000-4000-8000-000000000025','Derive o limite inferior','$H''(x)=-x^3$; portanto $H''(-1)=1$.',1),('70000000-0000-4000-8000-000000000042','40000000-0000-4000-8000-000000000026','Separe em zero','$\int_{-1}^0-xdx+\int_0^2xdx=1/2+2=5/2$.',1),('70000000-0000-4000-8000-000000000043','40000000-0000-4000-8000-000000000027','Resolva para $c$','$[x^2]_0^c=c^2=8$; isto dá $c=\sqrt8$, não 2.',1)
